import{_ as e,H as s,f as i,i as t}from"./chunks/framework.BauLNg70.js";const h=JSON.parse('{"title":"Apuntar tu mod a un juego concreto","description":"","frontmatter":{},"headers":[],"relativePath":"es/targeting-games.md","filePath":"es/targeting-games.md"}'),o={name:"es/targeting-games.md"};function n(l,a,p,r,d,c){return s(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="apuntar-tu-mod-a-un-juego-concreto" tabindex="-1">Apuntar tu mod a un juego concreto <a class="header-anchor" href="#apuntar-tu-mod-a-un-juego-concreto" aria-label="Permalink to &quot;Apuntar tu mod a un juego concreto&quot;">​</a></h1><p>Tu mod declara a qué juego va dirigido. Esta guía cubre cómo elegir el target correcto y por qué tu mod funcionará en distintos bundles (standalone, collections) sin que tengas que publicar varios.</p><hr><h2 id="target-gameid-—-la-decision-clave" tabindex="-1"><code>target.gameId</code> — la decisión clave <a class="header-anchor" href="#target-gameid-—-la-decision-clave" aria-label="Permalink to &quot;`target.gameId` — la decisión clave&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;gameId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snake-classic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;gameVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^2.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>gameId</code> es la <strong>identidad lógica</strong> del juego dentro del framework, no su nombre comercial ni AppID. Inmutable a lo largo de la vida del juego.</p><p>Lo encuentras en:</p><ul><li><code>docs/games/&lt;id&gt;/README.md</code> del repo del estudio.</li><li>La pantalla &quot;About&quot; del juego (suele mostrarlo).</li><li>La doc del SDK / host-api-changelog.</li></ul><p>Cuando dudes: pregunta al estudio. Es información pública.</p><hr><h2 id="por-que-no-apuntas-al-bundle" tabindex="-1">Por qué no apuntas al bundle <a class="header-anchor" href="#por-que-no-apuntas-al-bundle" aria-label="Permalink to &quot;Por qué no apuntas al bundle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ &quot;target.gameId&quot;: &quot;classics-collection&quot;</span></span>\n<span class="line"><span>❌ &quot;target.steamAppId&quot;: 1234567</span></span>\n<span class="line"><span>✅ &quot;target.gameId&quot;: &quot;snake-classic&quot;</span></span></code></pre></div><p>El framework está diseñado para que el mismo mod funcione en:</p><ul><li>Snake Classic standalone (Steam App ID 1234567)</li><li>Snake Classic dentro de Classics Collection (Steam App ID 4707310)</li></ul><p>Apuntar al <code>gameId</code> lógico te garantiza ambos sin esfuerzo. Apuntar al bundle te ataría a uno.</p><hr><h2 id="workshop-y-steam-appids" tabindex="-1">Workshop y Steam AppIDs <a class="header-anchor" href="#workshop-y-steam-appids" aria-label="Permalink to &quot;Workshop y Steam AppIDs&quot;">​</a></h2><p>Workshop publica contra un AppID. Tu mod aparece bajo el AppID que elijas para publicar.</p><p>El framework mantiene un mapping interno:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gameId &#39;snake-classic&#39; → AppIDs descubiertos: [1234567, 4707310]</span></span></code></pre></div><p>Esto significa: si publicas tu mod en Workshop bajo AppID 1234567 (standalone), los jugadores de Classics Collection (AppID 4707310) también lo verán y podrán instalarlo.</p><p>Recomendación: publica bajo el AppID <strong>standalone</strong> (suele tener más distribución). Si solo existe la collection, publica contra ese.</p><hr><h2 id="target-gameversion-—-rango-compatible" tabindex="-1"><code>target.gameVersion</code> — rango compatible <a class="header-anchor" href="#target-gameversion-—-rango-compatible" aria-label="Permalink to &quot;`target.gameVersion` — rango compatible&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;gameId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snake-classic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;gameVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^2.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>SemVer range:</p><ul><li><code>^2.0.0</code>: compatible con 2.0.0, 2.5.7, 2.99.99 — NO 3.0.0.</li><li><code>~2.0.0</code>: compatible con 2.0.x — NO 2.1.0.</li><li><code>&gt;=2.0.0 &lt;3.0.0</code>: explícito.</li></ul><p>Pon el rango más amplio que has testeado. Si solo probaste con 2.3.0:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;gameVersion&quot;: &quot;^2.3.0&quot;</span><span>   // bien</span></span>\n<span class="line"><span>&quot;gameVersion&quot;: &quot;^2.0.0&quot;</span><span>   // optimista; podría romperse con 2.0.x</span></span></code></pre></div><p>Después de testear con una version nueva del juego, <strong>publica una nueva versión de tu mod</strong> con el rango ampliado.</p><hr><h2 id="requires-hostapi-—-la-otra-mitad-del-contrato" tabindex="-1"><code>requires.hostApi</code> — la otra mitad del contrato <a class="header-anchor" href="#requires-hostapi-—-la-otra-mitad-del-contrato" aria-label="Permalink to &quot;`requires.hostApi` — la otra mitad del contrato&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;requires&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;hostApi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Esto compara contra el <code>host.api.version</code> del juego. Si la host API del juego pasa de 1.x a 2.x (breaking), tu mod queda <code>incompatible</code> hasta que publiques una versión con <code>requires.hostApi: &#39;^2.0.0&#39;</code>.</p><p>El estudio mantiene <code>docs/games/&lt;id&gt;/host-api-changelog.md</code> con cada cambio. Síguelo si quieres saber cuándo necesitas re-publicar.</p><hr><h2 id="requires-dlcs-—-dependencias-de-dlc" tabindex="-1"><code>requires.dlcs</code> — dependencias de DLC <a class="header-anchor" href="#requires-dlcs-—-dependencias-de-dlc" aria-label="Permalink to &quot;`requires.dlcs` — dependencias de DLC&quot;">​</a></h2><p>Si tu mod modifica contenido de un DLC:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;requires&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dlcs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snake-classic.endless-plus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>El loader verifica <code>EntitlementService.hasAccess()</code> antes de activar tu mod. Si el DLC no está owned, el mod aparece &quot;requiere DLC X&quot; con mensaje claro al jugador.</p><p>Para mods que <strong>funcionan sin DLC pero ganan funciones con él</strong>: no lo declares como required. Inspecciona <code>host.entitlements.getActiveDlcs()</code> en tu código y adapta el comportamiento.</p><hr><h2 id="multi-game-targets" tabindex="-1">Multi-game targets <a class="header-anchor" href="#multi-game-targets" aria-label="Permalink to &quot;Multi-game targets&quot;">​</a></h2><p><strong>No soportado</strong>: un mod apunta a <strong>un solo juego</strong>. Si quieres que funcione en varios juegos del framework, publica varios mods (uno por juego) compartiendo código común que tú mantengas.</p><p>Razón: cada juego tiene su propio host API, su propia policy, sus propias superficies. &quot;Un mod universal&quot; sería frágil.</p><hr><h2 id="resumen" tabindex="-1">Resumen <a class="header-anchor" href="#resumen" aria-label="Permalink to &quot;Resumen&quot;">​</a></h2><ul><li>Apunta al <code>gameId</code> lógico, no al AppID ni al nombre comercial.</li><li>Rangos SemVer en <code>target.gameVersion</code> y <code>requires.hostApi</code>.</li><li>Tu mod funciona automáticamente en standalone y en bundles (Classics Collection) que monten ese juego.</li><li>Workshop mapping: publica contra un AppID, descubierto desde todos.</li><li>DLCs requeridos declarados en <code>requires.dlcs[]</code>.</li></ul>',48)])])}const g=e(o,[["render",n]]);export{h as __pageData,g as default};
